        ["coworkee CLI"] = "coworkee-CLI",
        ["Empty: the global tool. Or a coworkee executable, or Coworkee.Cli.dll of a local build (runs with dotnet)."] = "Leer: das globale Tool. Oder eine coworkee-Programmdatei oder die Coworkee.Cli.dll eines lokalen Builds (läuft mit dotnet).",
        ["Template source"] = "Quelle der Vorlage",
        ["A Coworkee.Templates .nupkg or folder instead of nuget.org (coworkee new --template-source), for local builds."] = "Ein Coworkee.Templates-.nupkg oder Ordner statt nuget.org (coworkee new --template-source), für lokale Builds.",
        ["Local package feed"] = "Lokaler Paket-Feed",
