        ["npm once the packages of the release are on npm and the app should update them like any other npm dependency."] = "npm, sobald die Pakete des Releases auf npm sind und die App sie wie jede andere npm-Abhängigkeit aktualisieren soll.",
        ["Bundled: works offline and right after a release"] = "Mitgeliefert: funktioniert offline und direkt nach einem Release",
        ["npm: updates like other npm dependencies"] = "npm: Updates wie bei anderen npm-Abhängigkeiten",
        ["Bundled: the tarballs live in the app's repository"] = "Mitgeliefert: die Tarballs liegen im Repository der App",
        ["npm: needs the release on npmjs.com"] = "npm: braucht das Release auf npmjs.com",
